696	// runNormalizeJSON works like runNormalize but decodes result lines with
697	// json.Number, so tests can assert that high-precision numbers in extra
698	// survive normalization verbatim instead of being rounded into float64.
699	func runNormalizeJSON(t *testing.T, input string) []map[string]any {
700		t.Helper()
701		var out bytes.Buffer
702		failures, err := NormalizeReader(strings.NewReader(input), &out)
703		if err != nil {
704			t.Fatalf("NormalizeReader returned error: %v", err)
705		}
706		results := []map[string]any{}
707		dec := json.NewDecoder(bytes.NewReader(out.Bytes()))
708		dec.UseNumber()
709		for {
710			var m map[string]any
711			if err := dec.Decode(&m); err != nil {
712				if err == io.EOF {
713					break
714				}
715				t.Fatalf("decoding result: %v", err)
716			}
717			results = append(results, m)
718		}
719		if got := countFailures(results); got != failures {
720			t.Fatalf("NormalizeReader returned %d failures but output shows %d", failures, got)
721		}
722		return results
723	}
724	
725	// runNormalizeRaw returns the exact bytes NormalizeReader wrote, for
726	// assertions on the serialized form of preserved numbers.
727	func runNormalizeRaw(t *testing.T, input string) string {
728		t.Helper()
729		var out bytes.Buffer
730		if _, err := NormalizeReader(strings.NewReader(input), &out); err != nil {
731			t.Fatalf("NormalizeReader returned error: %v", err)
732		}
733		return out.String()
734	}
735	
736	func extraOf(t *testing.T, r map[string]any) map[string]any {
737		t.Helper()
738		event := eventOf(t, r)
739		extra, ok := event["extra"].(map[string]any)
740		if !ok {
741			t.Fatalf("event has no extra object: %#v", event)
742		}
743		return extra
744	}
745	
746	// mustNumber asserts v is a JSON number whose serialized form is exactly
747	// want — no rounding, no truncation, no conversion to string.
748	func mustNumber(t *testing.T, v any, want string) {
749		t.Helper()
750		n, ok := v.(json.Number)
751		if !ok {
752			t.Fatalf("expected JSON number %s, got %T (%v)", want, v, v)
753		}
754		if n.String() != want {
755			t.Fatalf("number preserved as %q, want %q", n.String(), want)
756		}
757	}
