	}
	if failures != 4 {
		t.Fatalf("exactly the four bad log lines must count as failures, got %d", failures)
	}
	results := decodeResults(t, out.Bytes())
	if len(results) != 6 {
		t.Fatalf("expected 6 records for 8 physical lines (two blank), got %#v", results)
	}

